# Break My Fix finding 1, generated by Tracefix: parse_tax_lvl raises NameError.
# Property (docstring): The returned dictionary only contains taxa for named ranks
# Quote: return a dictionary of taxa for its named ranks
# Run it with pytest: it fails for as long as the code breaks this property.

from kraken_biom import parse_tax_lvl, ranks


def test_break_my_fix_1() -> None:
    entry = {'pct_reads': '0.00', 'clade_reads': '1', 'taxon_reads': '0', 'rank': 'D', 'ncbi_tax': '2759', 'sci_name': 'Eukaryota'}
    result = parse_tax_lvl(entry={'pct_reads': '0.00', 'clade_reads': '1', 'taxon_reads': '0', 'rank': 'D', 'ncbi_tax': '2759', 'sci_name': 'Eukaryota'})
    assert (isinstance(result, dict) and all(k in ranks for k in result))
